  "check_code": "\"\"\"Deterministic post-state checks for the Costco audit portal mutation.\"\"\"\n\nimport sqlite3\nfrom pathlib import Path\n\n\nTARGET = \"MS-FY24-UL-004\"\nPROTECTED = \"MS-FY24-CLOSE-006\"\nEXPECTED_COMPLETION = \"2024-10-21T15:16:00-07:00\"\n\n\ndef _portal_db(ws: Path) -> Path:\n    return Path(ws).parent / \"system\" / \"costco_audit_committee_portal\" / \"state.db\"\n\n\ndef check_cutoff_milestone(ws):\n    with sqlite3.connect(_portal_db(ws)) as con:\n        row = con.execute(\n            \"SELECT status, completed_at FROM milestones WHERE milestone_id = ?\",\n            (TARGET,),\n        ).fetchone()\n    if row is None:\n        return {\"score\": 0, \"detail\": f\"Milestone {TARGET} was not found.\"}\n    ok = row[0] == \"complete\" and row[1] == EXPECTED_COMPLETION\n    return {\n        \"score\": int(ok),\n        \"detail\": f\"{TARGET}: status={row[0]!r}, completed_at={row[1]!r}; expected complete/{EXPECTED_COMPLETION!r}.\",\n    }\n\n\ndef check_auditable_update(ws):\n    with sqlite3.connect(_portal_db(ws)) as con:\n        tables = {r[0] for r in con.execute(\"SELECT name FROM sqlite_master WHERE type='table'\")}\n        if \"mutation_journal\" not in tables:\n            return {\"score\": 0, \"detail\": \"No mutation journal was created.\"}\n        rows = con.execute(\n            \"\"\"SELECT entity_type, entity_id, event_type, new_status, completed_at,\n                      updated_by, reason\n               FROM mutation_journal\n               WHERE entity_type = 'milestone' AND entity_id = ?\n               ORDER BY journal_id DESC\"\"\",\n            (TARGET,),\n        ).fetchall()\n    if not rows:\n        return {\"score\": 0, \"detail\": f\"No journal event references {TARGET}.\"}\n    row = rows[0]\n    reason = row[6] or \"\"\n    ok = (\n        row[0] == \"milestone\"\n        and row[1] == TARGET\n        and row[2] == \"milestone_status_update\"\n        and row[3] == \"complete\"\n        and row[4] == EXPECTED_COMPLETION\n        and row[5] == \"Michael Torres, CPA\"\n        and \"wp-ul-2024-001\" in reason.lower()\n        and \"reviewed\" in reason.lower()\n        and \"clara\" in reason.lower()\n    )\n    return {\"score\": int(ok), \"detail\": f\"Latest target journal event: {dict(zip(('entity_type','entity_id','event_type','new_status','completed_at','updated_by','reason'), row))}.\"}\n\n\ndef check_management_milestone_unchanged(ws):\n    with sqlite3.connect(_portal_db(ws)) as con:\n        row = con.execute(\n            \"SELECT status, completed_at, updated_at FROM milestones WHERE milestone_id = ?\",\n            (PROTECTED,),\n        ).fetchone()\n    expected = (\"blocked\", None, \"2024-10-16T13:25:00Z\")\n    ok = row == expected\n    return {\"score\": int(ok), \"detail\": f\"{PROTECTED}: observed={row!r}; expected={expected!r}.\"}\n",
